-- ============================================================================
-- 218 — إضافة قانون 133/1951 بمزاولة مهنة المحاسبة والمراجعة (35 مادة من 39) من نسخة الوقائع المصرية المقدمة من المالك
-- ----------------------------------------------------------------------------
-- المصدر: الوقائع المصرية العدد 81 فى 20 سبتمبر سنة 1951 (صورة ممسوحة ضوئياً قدمها المالك)، نُسخ النص بالقراءة البصرية مادةً مادة.
-- ما يشمله: المواد 1-30 و34 و35 و37 و38 و39 كما صدرت فى 1951، دون أى تعديل لاحق.
-- ما لا يشمله: المواد 31 و32 و33 (مجلس التأديب) و36 (العقوبات الجنائية) لأن ختماً وتلفاً فى الصورة يحجبان كلمات منها؛ لم يُخمَّن
--   منها شىء، وستُضاف فى هجرة لاحقة عند الحصول على صورة أوضح. لذلك ينص العنوان على أنها قيد الاستكمال.
-- تنبيهات: (1) هذا نص الإصدار الأول؛ الوضع الحالى للقانون وتعديلاته لم يُتحقق منه، لذلك الحالة 'amended'.
--   (2) المواد لا embedding لها بعد؛ تُضاف عند إعادة التضمين (مؤجلة بقرار المالك).
--   (3) المادة 15: فواصل النقاط المطبوعة بين جهات أعضاء اللجنة وصفاتهم حُذفت؛ أُبقيت صفة "رئيسا" وحُذفت كلمة "أعضاء" الطباعية الملحقة بآخر سطر.
-- الطريقة: إضافة فقط؛ لا تُعدَّل مادة موجودة، قابلة لإعادة التشغيل (ON CONFLICT DO NOTHING)، ولا تمس أى قانون آخر.
-- ============================================================================

CREATE TEMP TABLE m218_art (
  article_no int NOT NULL, loc text, body text NOT NULL, body_md5 text NOT NULL
) ON COMMIT DROP;

INSERT INTO m218_art VALUES
(1,'1 — السجل العام وشروط القيد فيه',$m218$لا يجوز أن يزاول مهنة المحاسبة أو المراجعة إلا من كان اسمه مقيدا فى السجل العام للمحاسبين والمراجعين بوزارة التجارة والصناعة، ويشمل هذا السجل ثلاثة جداول:
(أ) جدول المحاسبين والمراجعين تحت التمرين.
(ب) جدول المحاسبين والمراجعين.
(ج) جدول مساعدى المحاسبين والمراجعين.$m218$,'f1f981fca90570ff54a38594dadffda2'),
(2,'1 — السجل العام وشروط القيد فيه',$m218$مع عدم الإخلال بالأحكام الأخرى الواردة فى هذا القانون يشترط للقيد فى السجل العام أن يكون الطالب:
(1) مصريا مقيما فى المملكة المصرية.
(2) كامل الأهلية المدنية.
(3) حسن السمعة، لم تصدر عليه أحكام قضائية أو قرارات تأديبية ماسة بالشرف.$m218$,'04eee99a192eda619219832ed4a0832a'),
(3,'1 — السجل العام وشروط القيد فيه',$m218$استثناء من حكم المادة السابقة، يعفى من شرط الجنسية:
(1) المشتغلون بالمحاسبة أو المراجعة فى مصر عند العمل بهذا القانون والذين تتوافر فيهم الشروط الأخرى للقيد بالسجل.
(2) أعضاء جمعية المحاسبين والمراجعين الملكية المصرية المقيدون بها قبل تاريخ العمل بهذا القانون.$m218$,'dd2d14be8593170b95d4b2552e544b62'),
(4,'1 — السجل العام وشروط القيد فيه',$m218$يجوز لمؤسسات المحاسبة والمراجعة بمصر أن تستبدل بأعضائها من الأجانب أعضاء آخرين منهم ويشترط فى هذه الحالة:
(أ) أن يكون المستبدل عضوا بجمعية المحاسبين والمراجعين الملكية المصرية.
(ب) ألا تقل نسبة المصريين بين أعضائها عن النصف.
(ج) أن يكون قانون الدولة التى ينتمى اليها الأجنبى يجيز المعاملة بالمثل
ولا يجوز للعضو الأجنبى المستبدل مزاولة المهنة إلا بعد قيد اسمه فى الجدول ومحو اسم المستبدل به$m218$,'3887691640c02b2bb0d1cc7bde84ea04'),
(5,'1 — السجل العام وشروط القيد فيه',$m218$على المؤسسات المذكورة فى المادة السابقة أن تقدم لوزارة التجارة والصناعة خلال ثلاثين يوما من تاريخ العمل بهذا القانون بيانا بأسماء أعضائها وجنسية كل منهم ومؤهلاته.
ويصدر وزير التجارة والصناعة قرارا بتحديد تلك المؤسسات وعدد المحاسبين والمراجعين الأجانب الملحقين بها وقت العمل بهذا القانون واسم كل منهم وجنسيته ومؤهلاته.$m218$,'5af3a1fb0c27552f5708336e2a3decfb'),
(6,'1 — السجل العام وشروط القيد فيه — (أ) جدول المحاسبين والمراجعين تحت التمرين',$m218$يشترط للقيد فى جدول المحاسبين والمراجعين تحت التمرين أن يكون الطالب حاصلا على أحد المؤهلات الآتية:
(1) دبلوم مدرسة التجارة العليا
(2) بكالوريوس التجارة من شعبة المحاسبة.
(3) بكالوريوس المعهد العالى للعلوم المالية والتجارية.
(4) بكالوريوس التجارة من شعب ادارة الأعمال مع دبلوم معهد الضرائب ويشترط فى هذه المؤهلات أن تكون قد منحت للطالب من أحد معاهد التعليم المصرية.
(5) شهادة من أحد المعاهد الأجنبية تقرر وزارة المعارف العمومية بالاتفاق مع وزارة التجارة والصناعة اعتبارها معادلة لأحد المؤهلات الأربعة السابقة.$m218$,'2b7cb0fafe4e498c3b5f1c832004ceb9'),
(7,'1 — السجل العام وشروط القيد فيه — (أ) جدول المحاسبين والمراجعين تحت التمرين',$m218$استثناء من حكم المادة السابقة يقيد فى جدول المحاسبين والمراجعين تحت التمرين:
(1) الحاصلون على بكالوريوس التجارة من غير شعبة المحاسبة أو شعبة ادارة الأعمال مع دبلوم معهد الضرائب أو من يحصل على هذه المؤهلات قبل 31 ديسمبر سنة 1956.
(2) من حصل قبل تاريخ العمل بهذا القانون على دبلوم الدراسات التكميلية التجارية العالية.
(3) من حصل قبل تاريخ العمل بهذا القانون على دبلوم المعهد العالى للتجارة.$m218$,'69cbeb1ceb9e3cb0283e6b5932249ec7'),
(8,'1 — السجل العام وشروط القيد فيه — (ب) جدول المحاسبين والمراجعين',$m218$يشترط لنقل اسم الطالب من جدول المحاسبين والمراجعين تحت التمرين الى جدول المحاسبين والمراجعين أن يكون قد أمضى مدة التمرين المحددة بعد فى أعمال المحاسبة والمراجعة:
(أ) ثلاث سنوات للحاصلين على المؤهلات المنصوص عليها فى المادة 6
(ب) أربع سنوات للحاصلين على المؤهلات المنصوص عليها فى البند 1 من المادة 7
(ج) خمس سنوات للحاصلين على المؤهل المنصوص عليه فى البند 2 من المادة 7
(د) ست سنوات للحاصلين على المؤهل المنصوص عليه فى البند 3 من المادة 7، وتخفض هذه المدة إلى خمس سنوات للحاصلين منهم على دبلوم معهد الضرائب.$m218$,'c99083835a9734fb382ac2bf045766ea'),
(9,'1 — السجل العام وشروط القيد فيه — (ب) جدول المحاسبين والمراجعين',$m218$يشترط فى التمرين أن يكون الطالب قد زاول فعلا أعمال المحاسبة أو المراجعة بصورة جدية وبدون انقطاع طوال المدة فى مكتب أحد المحاسبين أو المراجعين المقيدين بالسجل.
ويثبت التمرين بشروطه بشهادة من المحاسب أو المراجع الذى قضى الطالب مدة التمرين بمكتبه.$m218$,'4ef70712d8d760cdda8466fc7d07368e'),
(10,'1 — السجل العام وشروط القيد فيه — (ب) جدول المحاسبين والمراجعين',$m218$يحسب من مدة التمرين كل زمن قضاه الطالب فى وظيفة مساعد مفتش بديوان المحاسبة أو مساعد مأمور أو مساعد مفتش بمصلحة الضرائب، أو خبير محاسب بوزارة العدل، أو مدرس لمادة المحاسبة أو المراجعة فى أحد معاهد التعليم الحكومية، أو رئيس حسابات فى احدى المصالح الحكومية أو المؤسسات المالية أو التجارية أو الصناعية أو التعاونية العامة أو فى أى عمل آخر يعتبر نظيرا لهذه الوظائف بقرار من وزير التجارة والصناعة بعد موافقة اللجنة المنصوص عليها فى المادة 15
ويحسب من مدة التمرين كذلك كل زمن قضاه الطالب فى مزاولة مهنة المحاسبة أو المراجعة فى مكتبه الخاص قبل تاريخ العمل بهذا القانون.$m218$,'31111a758004e89d4bbe3513f9c9c3ab'),
(11,'1 — السجل العام وشروط القيد فيه — (ب) جدول المحاسبين والمراجعين',$m218$مع عدم الإخلال بأحكام المادة الثالثة من هذا القانون يقيد بجدول المحاسبين والمراجعين مباشرة:
(1) أعضاء جمعية المحاسبين والمراجعين الملكية المصرية.
(2) الحاصلون على أحد المؤهلات المنصوص عليها فى المادة 6 والبند الأول من المادة 7 من هذا القانون، إذا كانوا قد زاولوا المهنة المدة المنصوص عليها فى المادة 8 بمكاتبهم الخاصة أو بمكتب أحد المحاسبين أو المراجعين قبل تاريخ العمل بهذا القانون.
(3) من اشتغلوا بمكاتبهم الخاصة فى مراجعة حسابات ثلاث شركات مساهمة على الأقل لمدة لا تقل عن خمس سنوات متتالية قبل تاريخ العمل بهذا القانون.
(4) الحاصلون على دبلوم التجارة المتوسطة الذين زاولوا مهنة المحاسبة أو المراجعة بمكاتبهم الخاصة مدة لا تقل عن عشر سنوات متتالية قبل تاريخ العمل بهذا القانون.
(5) الخبراء الحسابيون الذين زاولوا مهنتهم أمام المحاكم المصرية لمدة لا تقل عن عشر سنوات قبل تاريخ العمل بهذا القانون بشرط أن تقرر اللجنة المنصوص عليها فى المادة 15 كفايتهم العملية والعلمية لمزاولة مهنة المحاسبة والمراجعة.
(6) الحاصلون قبل تاريخ العمل بهذا القانون على دبلوم التجارة المتوسطة على الأقل أو على شهادة من أحد المعاهد الأجنبية التى تقرر وزارة المعارف العمومية باتفاق مع وزارة التجارة والصناعة اعتبارها معادلة للمؤهل المذكور وشغلوا بدون انقطاع وظيفة رئيس حسابات إحدى المصالح الحكومية أو المؤسسات المالية أو التجارية أو الصناعية أو التعاونية العامة أو أى عمل مماثل يصدر بتعيينه قرار من وزير التجارة والصناعة بعد موافقة اللجنة المشار اليها فى المادة 15 وذلك لمدة لا تقل عن عشر سنوات متتالية سابقة على تاريخ العمل بهذا القانون.$m218$,'2eec824188933eebfcefd660ca1c24ee'),
(12,'1 — السجل العام وشروط القيد فيه — (ج) جدول مساعدى المحاسبين والمراجعين',$m218$يقيد فى جدول مساعدى المحاسبين والمراجعين:
(أ) الحاصلون قبل تاريخ العمل بهذا القانون على دبلوم التجارة المتوسطة على الأقل أو على شهادة من أحد المعاهد الأجنبية التى تقرر وزارة المعارف العمومية بالاتفاق مع وزارة التجارة والصناعة اعتبارها معادلة للمؤهل المذكور بشرط أن يكونوا قد زاولوا بدون انقطاع مهنة المحاسبة أو المراجعة فى مكاتبهم الخاصة، أو كانوا مقيدين بجدول الخبراء المحاسبين أمام المحاكم المصرية، أو شغلوا بدون انقطاع وظيفة رئيس حسابات إحدى المصالح الحكومية أو المؤسسات المالية أو التجارية أو الصناعية أو التعاونية العامة أو أى عمل مماثل يصدر بتعيينه قرار من وزير التجارة والصناعة بعد موافقة اللجنة المشار اليها فى المادة 15 وذلك لمدة سنتين على الأقل سابقتين على تاريخ العمل بهذا القانون.
(ب) غير الحاصلين على أحد المؤهلات الدراسية المنصوص عليها فى البند السابق والذين يتوافر فيهم أحد الشروط الآتية:
(1) أن يكونوا قد اشتغلوا بمكاتبهم الخاصة بمراجعة حسابات شركات المساهمة مدة ثلاث سنوات متتالية على الأقل قبل تاريخ العمل بهذا القانون.
(2) أن يكونوا قد شغلوا بدون انقطاع وظيفة رئيس حسابات إحدى المؤسسات المالية أو التجارية أو الصناعية أو التعاونية العامة أو أى عمل مماثل يصدر بتعيينه قرار من وزير التجارة والصناعة بعد موافقة اللجنة المشار اليها فى المادة 15 مدة سبع سنوات على الأقل قبل تاريخ العمل بهذا القانون.
(3) أن يكونوا قد زاولوا مهنة المحاسبة أو المراجعة بمكاتبهم الخاصة مدة سبع سنوات على الأقل قبل تاريخ العمل بهذا القانون.
(4) أن يكونوا قد زاولوا مهنة المحاسبة أو المراجعة بمكاتبهم الخاصة مدة ثلاث سنوات على الأقل قبل تاريخ العمل بهذا القانون وأدوا بنجاح الامتحان الابتدائى المشار اليه فى المادة 14$m218$,'fb14c097396bcad4f43baeaa72e24675'),
(13,'1 — السجل العام وشروط القيد فيه — (ج) جدول مساعدى المحاسبين والمراجعين',$m218$لمساعدى المحاسبين والمراجعين نقل أسمائهم إلى جدول المحاسبين والمراجعين إذا قضوا فى مزاولة المهنة بهذه الصفة مدة ثلاث سنوات على الأقل وأدوا بنجاح الامتحان النهائى المشار اليه فى المادة 14 ويعمل بأحكام هذه المادة مدة سبع سنوات من تاريخ العمل بهذا القانون.
على أنه إذا كان مساعد المحاسب أو المراجع ممن تنطبق عليهم الفقرة "أ" والبنود 1 و2 و3 من الفقرة "ب" من المادة 12 قد أمضى قبل تاريخ العمل بهذا القانون مدة تزيد على الحد الأدنى المقرر له فى تلك المادة استقطعت الزيادة من مدة السنوات الثلاث الواردة فى الفقرة السابقة.$m218$,'4ef9eb528682d9654aaddee275373878'),
(14,'1 — السجل العام وشروط القيد فيه — (ج) جدول مساعدى المحاسبين والمراجعين',$m218$تنظم بمرسوم، بعد أخذ رأى اللجنة المنصوص عليها فى المادة 15، إجراءات الامتحانين الابتدائى والنهائى من حيث تحديد أدوار الامتحانات ومواعيدها وأماكنها وموادها ورسم دخولها، على ألا يزيد هذا الرسم على خمسة جنيهات للامتحان الابتدائى وعشرة جنيهات للامتحان النهائى.
ويصدر باختيار الممتحنين لكل دور قرار من وزير التجارة والصناعة بالاتفاق مع وزير المعارف العمومية.$m218$,'84100356d9c3c14a104d2b5cf9b4867f'),
(15,'2 — إجراءات القيد فى السجل',$m218$تقدم طلبات القيد فى أحد الجداول الثلاثة للجنة القيد وتؤلف هذه اللجنة من:
وكيل وزارة التجارة والصناعة (رئيسا)
وكيل ديوان المحاسبة أو نائبه عند غيابه
مستشار الدولة بقسم الرأى للادارة الخاصة بوزارة التجارة والصناعة أو نائبه عند غيابه
مدير عام مصلحة الضرائب أو نائبه عند غيابه
رئيس الغرفة التجارية المصرية لمدينة القاهرة أو نائبه عند غيابه
ثلاثة من أعضاء جمعية المحاسبين والمراجعين الملكية المصرية يعينون بقرار من وزير التجارة والصناعة لمدة سنتين، ويجوز تجديد تعيينهم.
وتكون مداولات اللجنة صحيحة بحضور ستة من أعضائها، وتصدر القرارات بأغلبية الآراء وعند التساوى يرجح الجانب الذى ينضم اليه الرئيس.$m218$,'7967b96a48bb114cabd39d1113a233b5'),
(16,'2 — إجراءات القيد فى السجل',$m218$يجب أن يتضمن طلب القيد اسم الطالب ولقبه وسنه وجنسيته ومحل إقامته ومؤهلاته العلمية وتاريخ حصوله عليها وتاريخ مزاولته المهنة.
ويجب أن ترفق بالطلب الأوراق المثبتة لتوافر الشروط المنصوص عليها فى هذا القانون.
وفى الحالات التى يشترط فيها القانون أن يكون الطالب قد زاول المهنة فى مكتبه وباسمه الخاص يجب عليه أن يثبت مدة مزاولته لها بتقديم مستندات رسمية من مصلحة الضرائب أو غيرها من الجهات الحكومية المختصة.$m218$,'b5d5b3a45e927b034cd6cbae34c07733'),
(17,'2 — إجراءات القيد فى السجل',$m218$تقرر اللجنة، بعد التحقق من توافر الشروط، قيد اسم الطالب فى السجل.
وإذا رأت اللجنة عدم توافر الشروط فى الطالب وجب عليها أن تؤجل الفصل فى طلبه وأن تعلن الطالب بالحضور أمامها بخطاب موصى عليه مصحوب بعلم الوصول لسماع أقواله قبل الفصل فى الطلب.
ويجب أن يكون قرار اللجنة برفض الطلب مسببا.
ويجب على اللجنة أن تفصل فى كل طلب فى مدى أربعة أشهر من تاريخ تقديمه، وأن تعلن الطالب بقرارها فور صدوره بالطريقة المتقدم ذكرها وإلا اعتبر الطلب مقبولا، ويستثنى من ذلك من كانوا يزاولون المهنة وقت العمل بهذا القانون فهؤلاء تمتد فترة الفصل فى طلباتهم ويستمرون فى مزاولة المهنة إلى أن يصدر قرار فى شأن قيد أسمائهم فى السجل، وذلك بشرط تقديم الطلب خلال شهرين من تاريخ العمل بالقانون.$m218$,'bacc3c36085470db4a316c3fc65f80e0'),
(18,'2 — إجراءات القيد فى السجل',$m218$إذا رفض الطلب لسوء سمعة الطالب، فلا يجوز له إعادة طلبه إلا بعد مضى خمس سنوات من تاريخ رفض طلبه إذا أثبت حسن سمعته طوال هذه المدة، كما يجوز له إعادة الطلب بمجرد رد اعتباره بحكم قضائى.
أما إذا كان رفض الطلب لعدم توافر شرط آخر جاز للطالب إعادة طلبه بمجرد توافر هذا الشرط.$m218$,'518b4ea9afd24920798a9f720d72237a'),
(19,'2 — إجراءات القيد فى السجل',$m218$رسم القيد بالسجل جنيه واحد للقيد فى جدول المحاسبين والمراجعين تحت التمرين، وجدول المساعدين، وخمسة جنيهات للقيد فى جدول المحاسبين والمراجعين.
وتسلم شهادة القيد بدون رسم.
وتعطى صور من قرارات اللجنة والسجل أو شهادات مستخرجة منها لمن يطلبها مقابل رسم قدره جنيه واحد.$m218$,'63069d329455d84e5f95682193fc7fe4'),
(20,'2 — إجراءات القيد فى السجل',$m218$تقوم وزارة التجارة والصناعة بنشر بيان سنوى بأسماء المزاولين لمهنة المحاسبة والمراجعة المقيدة أسماؤهم فى السجل العام.$m218$,'7b57421cdd68355a3a51f6c7aad3159e'),
(21,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$للمحاسب والمراجع تحت التمرين اعتماد ميزانيات وحسابات الشركات المختلفة ماعدا شركات المساهمة، وحسابات الممولين الخاضعين لضريبة الأرباح التجارية والصناعية الذين لا يزيد رأس مال الواحد منهم على عشرة آلاف جنيه أو لا تزيد أرباحه السنوية على ألف جنيه وفقا لآخر ميزانية اعتمدتها أو ربط أقرته مصلحة الضرائب،
وكذلك اعتماد حسابات الممولين الخاضعين للضريبة العامة على الإيراد إذا كان إيراد الواحد منهم لا يجاوز عشرة آلاف جنيه فى العام وفقا لآخر إقرار تم ربط الضريبة عليه، وله أن يحضر عن هذه الشركات وهؤلاء الممولين أمام مصلحة الضرائب ولجان الطعن وما فى حكمها من جهات الإدارة.
وليس للمحاسب أو المراجع تحت التمرين أن يفتح مكتبا باسمه الخاص، ولا يجوز له أن يباشر باسمه عملا من الأعمال الخارجة عن اختصاصه بمقتضى الفقرة السابقة أو الحضور فيها أمام مصلحة الضرائب ولجان الطعن وما فى حكمها، وإنما يكون ذلك باسم المحاسب أو المراجع الذى التحق بمكتبه وبطريق النيابة عنه.$m218$,'22515899058007db852a68c28072a21f'),
(22,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$لمساعد المحاسب أو المراجع اختصاص المحاسب أو المراجع تحت التمرين المنصوص عليه فى الفقرة الأولى من المادة السابقة.
وله أن يفتح مكتبا باسمه الخاص، ولكن ليس له أن ينوب عن المحاسبين أو المراجعين فى أعمالهم الخارجة عن هذا الاختصاص.$m218$,'71f8af1aeb60a690614827f285b7b1d0'),
(23,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$إذا كان المحاسب أو المراجع تحت التمرين، أو مساعد المحاسب أو المراجع، يباشر فى تاريخ العمل بهذا القانون عملية تزيد على النصاب المحدد له فيه، فلا تسرى عليه الأحكام المحددة للاختصاص إلا ابتداء من حسابات السنة المالية التالية لآخر سنة مالية كان يباشر حساباتها عند صدور هذا القانون.$m218$,'37496c7814d6b1b6d67733e256d92ed4'),
(24,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$مع عدم الإخلال بحكم المادة 25 يكون للمحاسب أو المراجع حق اعتماد ميزانيات وحسابات الشركات جميعها وحسابات الممولين الخاضعين لضريبة الأرباح التجارية والصناعية أو للضريبة العامة على الإيراد إطلاقا، وله الحضور عن الشركات والممولين أمام مصلحة الضرائب ولجان الطعن وما فى حكمها.$m218$,'b1b13c2fb2c0dd7f5c8fd3d563f21b93'),
(25,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$يشترط فى المحاسب أو المراجع لاعتماد ميزانيات شركات المساهمة:
(1) أن يكون ممن ينطبق عليهم أحد البندين 1 أو 3 من المادة 11 أو
(2) أن يكون قد زاول المهنة كمحاسب أو مراجع فى مكتب لحسابه الخاص مدة لا تقل عن خمس سنوات من تاريخ قيده بهذه الصفة.
ويحسب من هذه المدة الزمن الذى قضاه المحاسب أو المراجع فى إحدى الوظائف المنصوص عليها فى المادة 10 من هذا القانون.
ويسرى حكم هذه المادة بالنسبة إلى شركات المساهمة القائمة عند تاريخ العمل بهذا القانون ابتداء من حسابات السنة المالية التالية لتاريخ العمل به.$m218$,'1916dcac83d36fa3bc8b527016de01eb'),
(26,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$استثناء من حكم المادة السابقة يجوز لمن كان يزاول مهنة المحاسبة أو المراجعة فى مكتب لحسابه الخاص عند تاريخ العمل بهذا القانون ولم يتوافر فيه أحد الشرطين المنصوص عليهما فيها أن يقدم خلال ثلاثة أشهر من تاريخ العمل بهذا القانون طلبا للجنة المنصوص عليها فى المادة 15 للترخيص له باعتماد ميزانيات شركات المساهمة والحضور عنها أمام مصلحة الضرائب ولجان الطعن وما فى حكمها.
ولا يقبل الطلب إلا إذا توافرت فى الطالب الشروط الواردة فى المادتين 2 و 6، وكذلك الشروط التى يصدر بتعيينها قرار من وزير التجارة والصناعة بعد موافقة اللجنة المذكورة. ويكون قرار اللجنة فى الطلبات نهائيا.$m218$,'01a7831ea52f21f9a1756b2417ffb648'),
(27,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$لا يجوز لمن قيد اسمه فى السجل العام للمحاسبين والمراجعين الاشتغال بمهنة أخرى، أو القيام بأى عمل تجارى، إلا بعد الحصول على ترخيص بذلك من لجنة القيد.
ولا يجوز له أن يحاول الحصول على عمل من أعمال مهنته بطريق الإعلان أو بأى طريق يعتبر مخلا بكرامة المهنة.$m218$,'83f0ef212b823a34892a4287d14f7936'),
(28,'3 — حقوق المحاسبين والمراجعين وواجباتهم',$m218$يجب على كل من قيد اسمه فى السجل العام للمحاسبين والمراجعين أن يخطر وزارة التجارة والصناعة فى ظرف ثلاثين يوما بعنوان مكتبه أو المكتب الذى التحق به للتمرين فيه، وكذلك عند كل تغيير دائم لعنوان المكتب.
وعليه أن يذكر رقم قيده بالجدول ونوع الجدول المقيد فيه فى جميع المكاتبات والمطبوعات والشهادات التى تصدر منه.$m218$,'bf5af5b2a5bf8f31958fd07ded337087'),
(29,'4 — العقوبات التأديبية',$m218$يحاكم تأديبيا كل من زاول المهنة على وجه يخالف أحكام هذا القانون.$m218$,'1dfcad41a0408ee11a40ada8c5ee7108'),
(30,'4 — العقوبات التأديبية',$m218$العقوبات التأديبية هى:
(1) الإنذار.
(2) التوبيخ.
(3) الحرمان من مزاولة المهنة مدة لا تزيد على سنتين.
(4) محو الاسم من السجل.$m218$,'f5df75bf70822e61b82edf6e23045a4f'),
(34,'4 — العقوبات التأديبية',$m218$إذا فقد أحد المقيدين فى السجل أحد شروط الأهلية المنصوص عليها فى هذا القانون أحال وزير التجارة والصناعة أمره إلى لجنة القيد منعقدة بهيئة مجلس تأديب لينظر فى شأنه ويأمر، عند الاقتضاء، بمحو اسمه من السجل.$m218$,'f832c8e800c72efe7c8503e3fd4d179a'),
(35,'4 — العقوبات التأديبية',$m218$يجوز لمن صدر قرار بمحو اسمه لمخالفته أحكام هذا القانون أن يطلب من مجلس التأديب، بعد مضى خمس سنوات من تاريخ القرار إعادة قيد اسمه فى السجل.
وإذا كان قرار المحو لفقد شرط حسن السمعة جاز له طلب إعادة قيد اسمه بمجرد صدور الحكم برد اعتباره أو بمجرد صدور الأمر بالعفو عنه عفوا شاملا.$m218$,'1c2a989cec95658765adb089fd5b1b3b'),
(37,NULL,$m218$يعاقب بغرامة لا تقل عن مائة قرش ولا تزيد على خمسمائة قرش كل من يخالف أحكام المادة 28 من هذا القانون.$m218$,'797600da41509907de95bef6dd3465b7'),
(38,NULL,$m218$يكون لمفتشى مصلحة التجارة وإدارة الشركات بوزارة التجارة والصناعة ولمفتشى مصلحة الضرائب بوزارة المالية صفة رجال الضبط القضائى لإثبات ما يقع مخالفا لأحكام هذا القانون.$m218$,'66d009de11cbae5f254cb98c3969c15f'),
(39,NULL,$m218$على وزراء التجارة والصناعة والمالية والمعارف العمومية والعدل كل فيما يخصه، تنفيذ هذا القانون.
ويصدر وزير التجارة والصناعة القرارات اللازمة لتنفيذه، ويعمل به من تاريخ نشره فى الجريدة الرسمية.$m218$,'fb059389f75f6660e7160d0ce8f56755');

DO $m218$
DECLARE
  v_law uuid;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_nover int;
BEGIN
  IF (SELECT count(*) FROM m218_art WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[218] تلف فى نص أحد المواد داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m218_art) <> 35 THEN
    RAISE EXCEPTION '[218] عدد المواد داخل الملف غير مطابق';
  END IF;

  SELECT id INTO v_law FROM laws WHERE country_code='EG' AND law_no=133 AND law_year=1951 AND kind='law';
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, country_code, kind, governance_scope)
    VALUES (133, 1951, 'قانون رقم 133 لسنة 1951 بمزاولة مهنة المحاسبة والمراجعة (نص الإصدار الأول كما نُشر بالوقائع المصرية العدد 81 فى 20/9/1951 دون التعديلات اللاحقة؛ المواد 31 و32 و33 و36 قيد الاستكمال)', 'قانون مزاولة مهنة المحاسبة والمراجعة (1951)', 'other', 'amended', NULL, DATE '1951-09-15', 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, 0, loc, body FROM m218_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
  SELECT a.id, 1, a.body, DATE '1951-09-20', 'active'
    FROM articles a JOIN m218_art m ON m.article_no = a.article_no
   WHERE a.law_id = v_law AND a.article_suffix_order = 0
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m218_art m ON m.article_no=a.article_no
   WHERE a.law_id=v_law AND a.article_suffix_order=0;
  IF v_cnt <> 35 THEN
    RAISE EXCEPTION '[218] عدد مواد القانون % بدل 35', v_cnt;
  END IF;
  SELECT count(*) INTO v_nover FROM articles a
   WHERE a.law_id=v_law AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id=a.id);
  IF v_nover <> 0 THEN
    RAISE EXCEPTION '[218] % مادة بلا نسخة', v_nover;
  END IF;
  RAISE NOTICE '[218] قانون 133/1951: جديد=%، مواد مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m218$;
